ON DUPLICATE KEY UPDATE
  name=VALUES(name), shortName=VALUES(shortName), category=VALUES(category),
  description=VALUES(description), floors=VALUES(floors),
  latitude=VALUES(latitude), longitude=VALUES(longitude),
  floorDetails=VALUES(floorDetails), accent=VALUES(accent),
  mapX=VALUES(mapX), mapY=VALUES(mapY), sortOrder=VALUES(sortOrder);
